import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.BG8d4IEm.js";const l="/assets/wechatPay.CR6WPDzr.jpg",b=JSON.parse('{"title":"wechatPay","description":"","frontmatter":{"title":"wechatPay","tags":"wechatPay","birth":"2017-03-16T00:00:00.000Z","modified":"2017-03-16T00:00:00.000Z"},"headers":[],"relativePath":"projects/wechat/wechatPay.md","filePath":"projects/wechat/wechatPay.md"}'),o={name:"projects/wechat/wechatPay.md"};function n(p,t,d,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="wechatpay" tabindex="-1">wechatPay <a class="header-anchor" href="#wechatpay" aria-label="Permalink to &quot;wechatPay&quot;">​</a></h1><p><strong>前言:微信支付</strong></p><hr><h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><h2 id="支付模式" tabindex="-1">支付模式 <a class="header-anchor" href="#支付模式" aria-label="Permalink to &quot;支付模式&quot;">​</a></h2><p>支持的支付模式</p><ol><li>刷卡支付 适用于线下面对面收银场景</li><li>扫码支付 商户系统生成支付二维码,无需面对面的支付方式</li><li>公众号支付 公众号内调用支付接口完成支付</li><li>APP 支付 调用微信 sdk 接口完成支付行为</li></ol><h2 id="技术术语" tabindex="-1">技术术语 <a class="header-anchor" href="#技术术语" aria-label="Permalink to &quot;技术术语&quot;">​</a></h2><ul><li><strong>微信公众平台</strong> 微信提供企业服务的轻应用</li><li><strong>微信开放平台</strong> 提供给第三方调用微信接口的能力.为开发者模式</li><li><strong>微信商户平台</strong> 提供微信支付的功能平台</li><li><strong>微信企业号</strong> 不清楚?</li><li><strong>微信支付系统</strong> 实现微信支付等逻辑的系统</li><li><strong>商户收银系统</strong> POS 收银机,用来录入商品信息,生成订单,客户支付,打印小票的机器 <ul><li>需要搞清楚 POS 机软体的运行方式</li></ul></li><li><strong>商户后台系统</strong> 商户后台处理业务逻辑的总称</li><li><strong>商户证书</strong> 提供二进制文件，作为微信支付的后台凭证</li><li><strong>签名</strong> 常用签名算法 MD5,SHA128,SHA256,HMAC</li><li><strong>openId</strong> 用户在公众号下的唯一标识</li><li><strong>mch_id</strong> 微信支付对应的商户 id 号</li><li><strong>api 秘钥</strong> 商户系统和微信后台进行交易的接口秘钥</li><li><strong>Appid</strong> 公众号 id</li><li><strong>Appsecret</strong> 公众号秘钥</li></ul><p>对于开发重点关注的参数如下:</p><p><strong>APPID</strong> 微信服务号对应的识别 id <strong>mch_id</strong> 开通微信支付后对应的商户账号 <strong>API 密钥</strong> 支付交易中的签名密钥,用于微信核对支付信息 <strong>Appsecret</strong> 调用微信接口的凭证</p><p>详情参见 <a href="https://pay.weixin.qq.com/wiki/doc/api/micropay.php?chapter=3_1" target="_blank" rel="noreferrer">支付账户</a></p><h2 id="微信支付协议规范" tabindex="-1">微信支付协议规范 <a class="header-anchor" href="#微信支付协议规范" aria-label="Permalink to &quot;微信支付协议规范&quot;">​</a></h2><ol><li>采用 https 的方式传输</li><li>采用 post 方式提交</li><li>采用 xml 进行数据交互</li><li>采用 utf8 编码</li><li>签名算法进行接口验证</li><li>签名要求 <ol><li><p>将所有非空的参数按照字典排序生成 stringA</p></li><li><p>生成摘要</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span> </span></span>
<span class="line"><span>   stringSignTemp=&quot;stringA&amp;key=192006250b4c09247ec02edce69f6a2d&quot;</span></span>
<span class="line"><span>   sign=MD5(stringSignTemp).toUpperCase()=&quot;9A0A8659F005D6984697E2CA0A9CF3B7&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><p>将生成的新字段添加到传入参数中，作为一个新字段 字段中有一个 <code>nonce_str</code> 为随机项，用来保证签名的不可预测性。</p></li><li><p>微信证书的说明 <a href="https://pay.weixin.qq.com/wiki/doc/api/jsapi.php?chapter=4_3" target="_blank" rel="noreferrer">微信证书的作用</a></p></li></ol></li><li>证书要求</li><li>逻辑判断 <ol><li>先判断协议字段，错误返回</li><li>再判断业务，错误返回</li><li>最后判断交易状态，错误返回</li></ol></li></ol><h1 id="支付开发" tabindex="-1">支付开发 <a class="header-anchor" href="#支付开发" aria-label="Permalink to &quot;支付开发&quot;">​</a></h1><h2 id="支付字段规定" tabindex="-1">支付字段规定 <a class="header-anchor" href="#支付字段规定" aria-label="Permalink to &quot;支付字段规定&quot;">​</a></h2><h3 id="对应支付选择" tabindex="-1">对应支付选择 <a class="header-anchor" href="#对应支付选择" aria-label="Permalink to &quot;对应支付选择&quot;">​</a></h3><p>在不同支付场景使用对应开发接口。 其中选择方式如下。</p><table tabindex="0"><thead><tr><th style="text-align:left;">使用场景</th><th>支付模式</th><th>商品字段规则</th><th>样例</th><th>备注</th></tr></thead><tbody><tr><td style="text-align:left;">PC 网站</td><td>扫码支付</td><td>商品主页-商品描述</td><td>qq 会员充值</td><td>无</td></tr><tr><td style="text-align:left;">微信浏览器</td><td>公众号支付</td><td>商家名称-销售商品类目</td><td>逻辑思维-图书</td><td>线上商店，商家名称必须为实际销售商品店家</td></tr><tr><td style="text-align:left;">门店扫码</td><td>公众号支付</td><td>店名-销售商品类目</td><td>天虹南山店-超市</td><td>线下门店支付</td></tr><tr><td style="text-align:left;">门店扫码</td><td>扫码支付</td><td>店名-销售商品类目</td><td>天虹南山店-超市</td><td>线下门店支付</td></tr><tr><td style="text-align:left;">门店刷卡</td><td>刷卡支付</td><td>店名-销售商品类目</td><td>天虹南山店-超市</td><td>线下门店支付</td></tr><tr><td style="text-align:left;">第三方手机浏览器</td><td>H5 支付</td><td>主页 title 名-商品概述</td><td>腾讯充值中心-QQ会员充值</td><td></td></tr><tr><td style="text-align:left;">第三方 APP</td><td>APP 支付</td><td>应用市场 APP 名-商品概述</td><td>天天爱消除-游戏充值</td><td></td></tr></tbody></table><p><a href="https://mp.weixin.qq.com/wiki" target="_blank" rel="noreferrer">微信门店详解</a></p><h3 id="金额要求" tabindex="-1">金额要求 <a class="header-anchor" href="#金额要求" aria-label="Permalink to &quot;金额要求&quot;">​</a></h3><p><strong>微信支付金额限定在对应币种的最小单位</strong></p><p>交易类型</p><ul><li>JSAPI-- 公众号支付</li><li>NATIVE -- 原生扫码支付</li><li>APP -- app 支付，以上利用统一支付接口进行调用</li><li>MICROPAY -- 有单独的接口</li></ul><p>货币种类</p><ul><li>CNY 人民币</li></ul><p>时间必须为北京时间，精确到秒</p><p>商户订单号，由商户自行生成，必须保证唯一性（采用系统时间加随机序列来生成订单号） 具体规则。 * 若支付失败重新支付，使用原订单号 * 已支付或关闭撤销订单需重新生成订单号</p><p>银行类型参见下表 <a href="https://pay.weixin.qq.com/wiki/doc/api/micropay.php?chapter=4_2" target="_blank" rel="noreferrer">参数规定</a></p><p><a href="https://pay.weixin.qq.com/wiki/doc/api/micropay.php?chapter=4_3" target="_blank" rel="noreferrer">证书功能详解</a></p><h2 id="支付前期准备" tabindex="-1">支付前期准备 <a class="header-anchor" href="#支付前期准备" aria-label="Permalink to &quot;支付前期准备&quot;">​</a></h2><p>准备工作，必须包含如下条件</p><ul><li>有认证了的服务号并且开通了微信支付</li><li>获取如下信息写入微信官方 demo 配置文件 <ul><li><strong>AppID</strong> 绑定微信支付的服务号</li><li><strong>AppSecret</strong> 绑定微信支付的服务号密码</li><li><strong>Mch_id</strong> 商户编号,微信支付-&gt;商户信息查看</li><li><strong>APIKey</strong> 商户支付密钥,在微信支付中使用的密钥, 商户 -&gt; api 安全查看</li><li><strong>SSLCERT_PATH</strong></li><li><strong>SSLKEY_PATH</strong></li></ul></li></ul><p>支付开发流程如下</p><ol><li><p>配置微信公众平台</p><ol><li>开发基本配置保证服务器的正常连接</li><li>设置，公众号设置 -&gt; 功能设置中允许域名接口</li><li>微信支付中修改支付授权目录和支付回调 url</li><li>安装对应证书</li></ol></li><li><p>利用参看 <a href="https://mp.weixin.qq.com/wiki/17/c0f37d5704f0b64713d5d2c37b468d75.html" target="_blank" rel="noreferrer">微信授权</a>获取 code</p></li></ol><p><a href="https://open.weixin.qq.com/connect/oauth2/authorize?appid=wx37bcdb3936e6fb03&amp;connect_redirect=1&amp;redirect_uri=http:%2F%2F1.zsyd.applinzi.com%2FYDPAY%2Fcharge.test.php&amp;response_type=code&amp;scope=snsapi_base&amp;state=STATE" target="_blank" rel="noreferrer">https://open.weixin.qq.com/connect/oauth2/authorize?appid=wx37bcdb3936e6fb03&amp;connect_redirect=1&amp;redirect_uri=http:%2F%2F1.zsyd.applinzi.com%2FYDPAY%2Fcharge.test.php&amp;response_type=code&amp;scope=snsapi_base&amp;state=STATE</a></p><ol start="3"><li><p>利用 code 获取 opneid</p></li><li><p>利用 openid 生成账单</p></li><li><p>利用账单调用微信支付接口</p></li></ol><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><h3 id="redirect-url-错误" tabindex="-1">redirect_url 错误 <a class="header-anchor" href="#redirect-url-错误" aria-label="Permalink to &quot;redirect_url 错误&quot;">​</a></h3><p>去公众号设置-&gt;功能设置中修改文件路径即可 添加网页授权路径即可.</p><ol><li>必须精确到调用支付的文件夹</li><li>不允许有 <code>_</code> 为字符的文件名</li><li><strong>支付路径必须和公众号中设置的完全一样,特别是 <code>//</code> <code>/</code> 的问题</strong></li></ol><h3 id="不使用微信库如何获取-openid" tabindex="-1">不使用微信库如何获取 openId <a class="header-anchor" href="#不使用微信库如何获取-openid" aria-label="Permalink to &quot;不使用微信库如何获取 openId&quot;">​</a></h3><p>参看 <a href="https://mp.weixin.qq.com/wiki/17/c0f37d5704f0b64713d5d2c37b468d75.html" target="_blank" rel="noreferrer">微信授权</a></p><p><a href="MP_verify_aD3mRHUdJlbXazQP.txt">论坛讨论</a></p><h3 id="支付中路径设置问题" tabindex="-1">支付中路径设置问题 <a class="header-anchor" href="#支付中路径设置问题" aria-label="Permalink to &quot;支付中路径设置问题&quot;">​</a></h3><p><img src="`+l+'" alt="" loading="lazy"></p><p><a href="http://www.mengyunzhi.com/share/develop-en/183-wepay-the-url-not-regestirer.html" target="_blank" rel="noreferrer">支付路径的坑</a></p><h3 id="微信公众号被查封处理步骤" tabindex="-1">微信公众号被查封处理步骤 <a class="header-anchor" href="#微信公众号被查封处理步骤" aria-label="Permalink to &quot;微信公众号被查封处理步骤&quot;">​</a></h3><p><a href="http://kf.qq.com/faq/170118UnqeUZ170118mUb6fu.html?pass_ticket=EiDyGZ30yCvUm%2Ffl6uysrqp2lByF%2FLonvOC6%2B0tZ9abuf7dQdEbXdZ96xWk2qxSB" target="_blank" rel="noreferrer">微信查封说明</a></p><h3 id="微信支付成功的正确判断" tabindex="-1">微信支付成功的正确判断 <a class="header-anchor" href="#微信支付成功的正确判断" aria-label="Permalink to &quot;微信支付成功的正确判断&quot;">​</a></h3><p><a href="https://pay.weixin.qq.com/wiki/doc/api/jsapi.php?chapter=7_1" target="_blank" rel="noreferrer">正确逻辑</a></p><h1 id="获取用户-openid" tabindex="-1">获取用户 openId <a class="header-anchor" href="#获取用户-openid" aria-label="Permalink to &quot;获取用户 openId&quot;">​</a></h1><p><a href="https://pay.weixin.qq.com/wiki/doc/api/micropay.php?chapter=4_4" target="_blank" rel="noreferrer">用户 openId</a></p><p>由于在微信体系中，用户 openId 对于不同公众号具有唯一性。 建议在用户注册阶段直接存入，数据库。方便后续调用。重点。</p><h1 id="api-详解" tabindex="-1">api 详解 <a class="header-anchor" href="#api-详解" aria-label="Permalink to &quot;api 详解&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">接口</th><th>功能</th></tr></thead><tbody><tr><td style="text-align:left;">刷卡支付</td><td>需要用户提供授权码</td></tr><tr><td style="text-align:left;">查询订单</td><td>用来获取支付订单状态</td></tr><tr><td style="text-align:left;">撤销订单</td><td>撤销订单，再支付成功以内的 7 天均有效，注意在支付 15 s 后才执行次操作</td></tr><tr><td style="text-align:left;">退款接口</td><td>支持对金额的返回，一年之内有效，</td></tr><tr><td style="text-align:left;">退款状态查询</td><td>零钱支付 20 分钟内返还，银行卡最长为 3 天时间</td></tr></tbody></table><p>采用微信平台进行微信测试</p><p><a href="http://www.jianshu.com/p/2cb959529c96#comments" target="_blank" rel="noreferrer">用户充值原理</a></p><h2 id="企业付款" tabindex="-1">企业付款 <a class="header-anchor" href="#企业付款" aria-label="Permalink to &quot;企业付款&quot;">​</a></h2><p><a href="https://pay.weixin.qq.com/wiki/doc/api/tools/mch_pay.php?chapter=14_2" target="_blank" rel="noreferrer">微信企业支付</a></p>',60)])])}const m=e(o,[["render",n]]);export{b as __pageData,m as default};
